SELECT t.* FROM ( SELECT h.*, p.project_number, p.project_name, ( SELECT b.bp_name FROM hls_bp_master b WHERE b.bp_id = p.tenant_id ) prj_bp_name, ( SELECT s.MEANING FROM sys_code_value_b_v s WHERE s. CODE = 'HLS.DURATION_STATUS' AND s.code_value = h.duration_status ) duration_status_n, (SELECT u.description FROM sys_user u WHERE u.user_id = h.apply_person) apply_person_n, (SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = h.apply_unit_id) apply_unit_id_n, p.assist_project_manager, p.business_type, (SELECT max(fa.SOURCE_PK_VALUE) FROM fnd_atm_attachment fa, fnd_atm_attachment_multi faa, prj_project_attachment ha WHERE fa.ATTACHMENT_ID = faa.ATTACHMENT_ID AND faa.TABLE_PK_VALUE = ha.PROJECT_ATTACHMENT_ID and ha.PROJECT_ATTACHMENT_CATEGORY='HLS_PRJ_PROJECT_DOCX3' and faa.TABLE_NAME = 'HLS_PRJ_PROJECT_DOCX3_CHANGE' AND ha.project_id = p.project_id)source_pk_value3, (select a.approval_id from prj_project_approval a where a.project_id = p.project_id and a.data_class = 'CHANGE')approval_id, (select q.FINANCE_AMOUNT from prj_quotation q where q.SOURCE_DOCUMENT_ID = p.project_id and q.data_class = 'PRJ_PROJECT_INVEST' and q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT')finance_amount FROM hls_duration_hd h, prj_project P WHERE h.duration_type = 'REPLY' AND h.project_id = p.project_id AND p.data_class = 'NORMAL' ) t
1=1
and t.hd_id = #{hdId}
and (t.apply_person = #{applyPerson} or (select distinct b.role_code from sys_user_allocation a,sys_role_b b where a.role_id = b.role_id and a.user_id = #{applyPerson} and b.role_code = 'ADMIN') = 'ADMIN')
and t.duration_number like #{durationNumber}
and t.prj_bp_name like #{prjBpName}
and t.project_name like #{projectName}
and t.project_number like #{projectNumber}
and t.apply_date >= #{applyDateFrom}
and t.apply_date <= #{applyDateTo}
and t.duration_status = #{durationStatus}
order by t.creation_date desc

