 WHERE fou.unit_id = p.host_unit_id ) host_unit_name, ( SELECT s.description FROM sys_user s WHERE s.user_id = p.assist_project_manager ) assist_project_manager_n, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = p.assist_unit_id ) assist_unit_name, nvl(p.finance_amount, 0) AS prj_finance_amount, ( SELECT s.MEANING FROM sys_code_value_b_v s WHERE s. CODE = 'HLS.EXECUTE_TYPE' AND s.code_value = hd.execute_type ) execute_type_n, ( SELECT s.MEANING FROM sys_code_value_b_v s WHERE s. CODE = 'HLS.DURATION_STATUS' AND s.code_value = hd.execute_status ) execute_status_n FROM hls_duration_hd hd LEFT JOIN con_contract c ON c.contract_id = hd.contract_id LEFT JOIN prj_project p ON hd.project_id = p.project_id ) t
