SELECT t.*, t.contract_number AS contract_id_n FROM (SELECT hd.*, (case when hd.duration_type = 'PROJECT' then (select wm_concat(cc2.contract_number) from hls_duration_ln ln, con_contract cc2 where ln.hd_id = hd.hd_id and ln.contract_id = cc2.contract_id) else c.contract_number end) contract_number, p.ref_project_id, (SELECT meaning FROM sys_code_value_b_v v WHERE v.code = 'CON.CONTRACT_STATUS' AND v.code_value = c.contract_status) contract_status_n, c.contract_name, nvl(c.overdue_max_days, 0) overdue_max_days, nvl(c.finance_amount, 0) finance_amount, (SELECT SUM(cc.principal - nvl(cc.received_principal, 0)) FROM con_contract_cashflow cc WHERE cc.contract_id = c.contract_id AND cc.cf_item = 1 AND cc.cf_status = 'RELEASE') outstanding_principal, (SELECT u.unit_name FROM fnd_org_unit u WHERE u.unit_id = c.unit_id) unit_name, (SELECT ee.name FROM fnd_employee ee WHERE c.employee_id = ee.employee_id) employee_name, (SELECT bp.bp_name FROM hls_bp_master bp WHERE bp.bp_id = c.tenant_id) bp_id_n, (SELECT bp.bp_id FROM hls_bp_master bp WHERE bp.bp_id = c.tenant_id) bp_id, (SELECT bp.bp_name FROM hls_bp_master bp WHERE bp.bp_id = c.tenant_id) bp_name, (SELECT s.MEANING FROM sys_code_value_b_v s WHERE s.CODE = 'HLS.DURATION_TYPE_NEW' AND s.code_value = hd.duration_type) duration_type_n, (SELECT s.MEANING FROM sys_code_value_b_v s WHERE s.CODE = 'HLS.DURATION_STATUS' AND s.code_value = hd.duration_status) duration_status_n, (SELECT u.description FROM sys_user u WHERE u.user_id = hd.apply_person) apply_person_n, (SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = hd.apply_unit_id) apply_unit_id_n, (case when hd.duration_type = 'PROJECT' then (select wm_concat(pp.contract_number) from hls_duration_ln ln, con_contract cc2, prj_project pp where ln.hd_id = hd.hd_id and ln.contract_id = cc2.contract_id and pp.project_id = cc2.project_id) else p.contract_number end) AS prj_con_number, p.contract_number AS project_id_n, (case when hd.duration_type = 'PROJECT' then (select wm_concat(pp.contract_name) from hls_duration_ln ln, con_contract cc2, prj_project pp where ln.hd_id = hd.hd_id and ln.contract_id = cc2.contract_id and pp.project_id = cc2.project_id) else p.project_name end) project_name, (case when hd.duration_type = 'PROJECT' then (select wm_concat(bp.bp_name) from hls_duration_ln ln, con_contract cc2, prj_project pp, hls_bp_master bp where ln.hd_id = hd.hd_id and ln.contract_id = cc2.contract_id and pp.project_id = cc2.project_id and bp.bp_id = pp.tenant_id) else (SELECT bp.bp_name FROM hls_bp_master bp WHERE bp.bp_id = p.tenant_id) end) prj_bp_name, (SELECT t1.description FROM hls_document_status t1 WHERE t1.document_category = 'CON_CONTRACT' AND t1.status_code = nvl(p.contract_status, 'NEW')) prj_con_status_n, (SELECT u.unit_name FROM fnd_org_unit u WHERE u.unit_id = p.unit_id) prj_unit_name, (SELECT ee.name FROM fnd_employee ee WHERE ee.employee_id = p.employee_id) prj_employee_name, (select s.description from sys_user s where s.user_id = p.host_project_manager) host_project_manager_n, (select fou.unit_name from fnd_org_unit fou where fou.unit_id = p.host_unit_id) host_unit_name, (select s.description from sys_user s where s.user_id = p.assist_project_manager) assist_project_manager_n, (select fou.unit_name from fnd_org_unit fou where fou.unit_id = p.assist_unit_id) assist_unit_name, nvl(p.finance_amount, 0) AS prj_finance_amount, nvl((SELECT SUM(nvl(ccc.principal, 0) - nvl(ccc.received_principal, 0)) FROM con_contract cc, con_contract_cashflow ccc WHERE cc.project_id = p.project_id AND cc.data_class = 'NORMAL' AND ccc.cf_item = 1 AND ccc.cf_status = 'RELEASE' AND ccc.contract_id = cc.contract_id), 0) prj_outstanding_principal, nvl((SELECT MAX(nvl(c.overdue_max_days, 0)) FROM con_contract c WHERE c.project_id = p.project_id AND c.data_class = 'NORMAL'), 0) AS prj_overdue_max_days, (SELECT s.MEANING FROM sys_code_value_b_v s WHERE s.CODE = 'HLS.EXECUTE_TYPE' AND s.code_value = hd.execute_type) execute_type_n,
(SELECT s.MEANING FROM sys_code_value_b_v s WHERE s.CODE = 'HLS.DURATION_STATUS' AND s.code_value = hd.execute_status) execute_status_n
FROM hls_duration_hd hd LEFT JOIN con_contract c ON c.contract_id = hd.contract_id LEFT JOIN prj_project p ON hd.project_id = p.project_id) t
